import { IndentationText, NewLineKind, Project, QuoteKind } from "ts-morph";
import { joinLines, line } from "../../../utils/strings/format";

export type AuthCredentials = {
    username?: string;
    password?: string;
    apiKeyName?: string;
    apiKeyValue?: string;
};

export function buildServiceEnvKey(fileBaseName: string): string {
    return fileBaseName.replace(/[^a-zA-Z0-9]/g, "_").toUpperCase();
}

export function renderBanner(): string {
    // Header banner indicating auto-generation
    const lines = [
        "/**",
        " * This file was auto-generated by generate-auth-helper.ts",
        " * Values are resolved from environment variables, falling back to endpoint config values if present.",
        " * Check in before editing this file manually.",
        " */",
        "",
    ];

    return joinLines(lines);
}

export function renderApiKeyAuth(args: {
    serviceEnvKey: string;
    credentials?: AuthCredentials;
}): string {
    const {serviceEnvKey, credentials} = args;

    // Use apiKeyName from credentials or default to "x-api-key"
    const headerName = credentials?.apiKeyName ?? "x-api-key";
    const fallbackApiKeyValueLiteral = JSON.stringify(credentials?.apiKeyValue ?? "");

    const lines = [
        "/**",
        " * Returns headers containing the API key for authentication.",
        ` * Expected env vars: ${serviceEnvKey}_APIKEY`,
        " */",
        "export function getAuthHeaders() {",
        line(1, `const apiKey = process.env[\"${serviceEnvKey}_APIKEY\"] ?? ${fallbackApiKeyValueLiteral};`),
        line(1, "return {"),
        line(2, `${JSON.stringify(headerName)}: apiKey`),
        line(1, "};"),
        "}",
        "",
    ];

    return joinLines(lines);
}

export function renderBasicAuthUsingTsMorph(args: {
    serviceEnvKey: string;
    credentials?: AuthCredentials;
}): string {
    const {serviceEnvKey, credentials} = args;

    const project = new Project({
        useInMemoryFileSystem: true,
        manipulationSettings: {
            // Match the style of the existing template output.
            indentationText: IndentationText.TwoSpaces,
            newLineKind: NewLineKind.LineFeed,
            quoteKind: QuoteKind.Double,
            insertSpaceAfterOpeningAndBeforeClosingNonemptyBraces: true,
            useTrailingCommas: false,
        },
    });

    const sf = project.createSourceFile("auth-helper.basic.ts", "", {overwrite: true});

    // Keep the existing JSDoc block text identical.
    sf.addStatements(`/**
 * Returns headers containing the Basic Authentication token.
 * Expected env vars: ${serviceEnvKey}_USERNAME, ${serviceEnvKey}_PASSWORD
 */`);

    sf.addFunction({
        isExported: true,
        name: "getAuthHeaders",
        statements: (writer) => {
            writer.writeLine(
                `const username = process.env["${serviceEnvKey}_USERNAME"] ?? "${credentials?.username ?? ""}";`
            );
            writer.writeLine(
                `const password = process.env["${serviceEnvKey}_PASSWORD"] ?? "${credentials?.password ?? ""}";`
            );
            writer.writeLine(
                `const encoded = Buffer.from(username + ":" + password).toString("base64");`
            );
            writer.writeLine("return {");
            writer.indent(() => {
                writer.writeLine(`Authorization: "Basic " + encoded`);
            });
            writer.writeLine("};");
        },
    });

    // Ensure a trailing newline, matching the original template strings.
    const text = sf.getFullText();
    return text.endsWith("\n") ? text : text + "\n";
}

export function renderBasicAuth(args: {
    serviceEnvKey: string;
    credentials?: AuthCredentials;
}): string {
    const {serviceEnvKey, credentials} = args;
    return renderBasicAuthUsingTsMorph({serviceEnvKey, credentials});
}

export function renderNoneAuth(): string {
    const lines = [
        "/**",
        " * Returns empty headers as no authentication is required.",
        " */",
        "export function getAuthHeaders() {",
        line(1, "return {};"),
        "}",
        "",
    ];

    return joinLines(lines);
}

export function renderAuthHelperContent(args: {
    fileBaseName: string;
    authType: "apikey" | "basic" | "none";
    credentials?: AuthCredentials;
}): string {
    const {fileBaseName, authType, credentials} = args;
    const serviceEnvKey = buildServiceEnvKey(fileBaseName);

    const banner = renderBanner();

    if (authType === "apikey") {
        return banner + renderApiKeyAuth({serviceEnvKey, credentials});
    }

    if (authType === "basic") {
        return banner + renderBasicAuth({serviceEnvKey, credentials});
    }

    if (authType === "none") {
        return banner + renderNoneAuth();
    }

    // Should be unreachable due to typing, but kept for runtime safety.
    throw new Error(
        `Unsupported authType '${authType}'. Supported types are 'apikey', 'basic', and 'none'.`
    );
}